<?php
declare(strict_types=1);

/**
 * install_mrl_team_redesign.php
 *
 * VERSION: v011
 * LAST MODIFIED: 8/27/2026 8:47:32 pm
 *
 * PURPOSE:
 * Targeted Light-theme readability fix for the verified working v010 page.
 *
 * EXPECTED INPUT:
 * - exact team_redesign.php v010 generated by the v010 installer
 *
 * OUTPUT:
 * - complete team_redesign.php VERSION: v011
 *
 * SAFETY:
 * - exact SHA-256 v010 baseline check
 * - backup before replacement
 * - only team_redesign.php is written
 * - support/profile/production files are hash-verified unchanged
 * - critical pick/chart/theme/menu signatures checked after installation
 *
 * CHANGELOG:
 *
 * v011 (8/27/2026 8:47:32 pm)
 * - FIX: Light-theme pick-status and submission-status text becomes black.
 * - FIX: Links inside those panels remain blue.
 * - PRESERVE: Dark/Cars/Starry Night and all application logic.
 */

date_default_timezone_set('America/New_York');

const EXPECTED_TEAM_SHA256='6dbc07c9a1f590be7254217e7f305cf8bfec7c788e17a33c48801e85c44ff209';

$base=__DIR__;
$team=$base.'/team_redesign.php';
$json=$base.'/mrl_team/mrl_team_page_content.json';
$manager=$base.'/mrl_team/admin_team_page_content.php';
$helper=$base.'/mrl_team/mrl_theme_helper.php';
$profile=$base.'/profile_redesign.php';
$prodTeam=$base.'/team.php';
$prodProfile=$base.'/profile.php';

function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
function sr(string $l,bool $ok,string $d=''):void{echo '<tr><td>'.h($l).'</td><td class="'.($ok?'ok':'bad').'">'.($ok?'PASS':'FAIL').'</td><td>'.h($d).'</td></tr>';}
function aw(string $p,string $d):bool{$t=$p.'.tmp_'.bin2hex(random_bytes(4));if(file_put_contents($t,$d,LOCK_EX)===false)return false;if(!@rename($t,$p)){@unlink($t);return false;}return true;}

$replacement=base64_decode('',true);
$replacementOk=is_string($replacement)
    && strpos($replacement,'VERSION: v011')!==false
    && strpos($replacement,'html.mrl-theme-light .mrl-rd-notice-panel *{color:#000!important}')!==false
    && strpos($replacement,'html.mrl-theme-light .mrl-rd-notice-panel a{color:#006eaa!important}')!==false;

$teamExists=is_file($team);
$teamHash=$teamExists?hash_file('sha256',$team):'';
$teamBaselineOk=$teamExists && $teamHash===EXPECTED_TEAM_SHA256 && strpos((string)file_get_contents($team),'VERSION: v010')!==false;

$protected=[$json,$manager,$helper,$profile,$prodTeam,$prodProfile];
$before=[];$protectedOk=true;
foreach($protected as $p){
    if(!is_file($p)){$protectedOk=false;$before[$p]='';}
    else{$before[$p]=hash_file('sha256',$p);}
}

$jsonOk=false;$panelCounts=[];
if(is_file($json)){
    $raw=file_get_contents($json);$data=is_string($raw)?json_decode($raw,true):null;
    if(is_array($data)){
        $jsonOk=true;
        foreach(['admin_league_panel','admin_hosting_panel','league_panel','team_panel'] as $key){
            $items=$data[$key]['items']??null;
            $panelCounts[$key]=is_array($items)?count($items):-1;
            if($panelCounts[$key]<0)$jsonOk=false;
        }
    }
}

$apply=isset($_POST['apply'])&&$_POST['apply']==='1';
$msgs=[];$success=false;

if($apply&&$replacementOk&&$teamBaselineOk&&$protectedOk&&$jsonOk){
    $backupDir=$base.'/_migration_backups/team_redesign_v011_'.date('Ymd_His');
    $ok=(is_dir($backupDir)||mkdir($backupDir,0755,true));
    if(!$ok){$msgs[]='Could not create backup directory.';}
    elseif(!copy($team,$backupDir.'/team_redesign.php')){$ok=false;$msgs[]='Could not back up team_redesign.php.';}
    else{$msgs[]='Backed up exact working v010 team_redesign.php.';}

    if($ok&&!aw($team,$replacement)){$ok=false;$msgs[]='Could not install team_redesign.php v011.';}
    elseif($ok){$msgs[]='Installed targeted team_redesign.php v011.';}

    if($ok){
        $installed=(string)file_get_contents($team);
        $checks=[
            'v011 header'=>strpos($installed,'VERSION: v011')!==false,
            'Light notice text black'=>strpos($installed,'html.mrl-theme-light .mrl-rd-notice-panel *{color:#000!important}')!==false,
            'Light notice links blue'=>strpos($installed,'html.mrl-theme-light .mrl-rd-notice-panel a{color:#006eaa!important}')!==false,
            'four-panel JSON loader'=>strpos($installed,'foreach ($teamPageContentPanelKeys as $panelKey)')!==false,
            'Cars theme'=>strpos($installed,'mrl-theme-cars')!==false,
            'Starry Night theme'=>strpos($installed,'mrl-theme-starry-night')!==false,
            'Dark theme'=>strpos($installed,'mrl-theme-dark')!==false,
            'Light theme'=>strpos($installed,'mrl-theme-light')!==false,
            'normal form route'=>strpos($installed,'include $currentForm;')!==false,
            'LP route'=>strpos($installed,"include 'team-late-pick.php';")!==false,
            'RP/RD route'=>strpos($installed,"include 'team_replacement_driver.php';")!==false,
            'current chart'=>strpos($installed,"include 'current_segment_chart.php';")!==false,
            'prior-year charts'=>strpos($installed,"include 'prior_year_user_team_chart.php';")!==false,
        ];
        foreach($checks as $label=>$pass){$msgs[]=($pass?'PASS: ':'FAIL: ').$label;if(!$pass)$ok=false;}
    }

    foreach($before as $p=>$hash){
        $same=$hash!==''&&is_file($p)&&$hash===hash_file('sha256',$p);
        $msgs[]=($same?'Verified unchanged: ':'ERROR changed: ').str_replace($base.'/','',$p);
        if(!$same)$ok=false;
    }

    $success=$ok;
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><title>MRL Team Redesign Installer v011</title>
<style>*{box-sizing:border-box}html{background:#111}body{margin:0;color:#eee;font-family:Tahoma,Verdana,Segoe UI,sans-serif}.wrap{width:94%;max-width:1150px;margin:20px auto}.card{background:#202020;border:1px solid #555;border-radius:14px;padding:20px;margin-bottom:16px}h1,h2{color:#efc982}table{width:100%;border-collapse:collapse}td{padding:9px;border-bottom:1px solid #444;vertical-align:top}.ok{color:#61e493}.bad{color:#ff7777}button{padding:11px 20px;background:#1466c9;color:#fff;border:1px solid #5a7fb5;border-radius:9px;font-weight:800;cursor:pointer}a,code{color:#76cfff}li{line-height:1.45;margin-bottom:5px}</style></head>
<body><div class="wrap">
<div class="card"><h1>MRL Team Redesign Installer v011</h1><p>Tiny Light-theme contrast fix. No structural or application-logic changes.</p></div>
<div class="card"><h2>Preflight</h2><table>
<?php sr('Exact working team_redesign.php v010 baseline',$teamBaselineOk,$teamHash); ?>
<?php sr('Complete v011 replacement embedded',$replacementOk,'Full-file replacement.'); ?>
<?php sr('Protected support/profile/production files present',$protectedOk,'Six files checked.'); ?>
<?php sr('Four-panel JSON readable',$jsonOk,$json); ?>
<?php foreach($panelCounts as $k=>$c): ?><?php sr('JSON '.$k,$c>=0,(string)$c.' item(s)'); ?><?php endforeach; ?>
</table></div>
<?php if($teamBaselineOk&&$replacementOk&&$protectedOk&&$jsonOk): ?>
<div class="card"><h2>What v011 changes</h2><ul>
<li>Light theme: pick-status notice text becomes black.</li>
<li>Light theme: submission-status panel text becomes black.</li>
<li>Links inside those panels remain blue.</li>
<li>Cars, Starry Night and Dark are untouched.</li>
<li>Charts, forms, menus, themes, profile and application logic are untouched.</li>
</ul><?php if(!$apply): ?><form method="post"><input type="hidden" name="apply" value="1"><button>Install v011 Light Fix</button></form><?php endif; ?></div><?php endif; ?>
<?php if($apply): ?><div class="card"><h2>Apply Result</h2><p class="<?php echo $success?'ok':'bad'; ?>"><strong><?php echo $success?'SUCCESS':'FAILED'; ?></strong></p><ul><?php foreach($msgs as $m): ?><li><?php echo h($m); ?></li><?php endforeach; ?></ul><?php if($success): ?><p><a href="/team_redesign.php" target="_blank">Open Team Redesign v011</a></p><?php endif; ?></div><?php endif; ?>
</div></body></html>